// Checkout conversion module: tracks paid events from checkout completion
// Integrates with revenue autopilot to increment paidEvents on successful payment

const fs = require('fs');
const path = require('path');

const REVENUE_LOG = '/var/log/revenue_autopilot.log';
const CONVERSION_LOG = '/var/log/checkout_conversion.log';

function logConversion(event) {
  const entry = {
    ts: new Date().toISOString(),
    event: event,
    source: 'checkout'
  };
  fs.appendFileSync(CONVERSION_LOG, JSON.stringify(entry) + '\n');
  // Also append to revenue log for autopilot
  fs.appendFileSync(REVENUE_LOG, JSON.stringify({...entry, type: 'paidEvent'}) + '\n');
}

// Simulate checkout completion hook (to be called by payment gateway)
function onCheckoutComplete(orderId, amount, currency) {
  logConversion({ orderId, amount, currency, status: 'completed' });
  return { success: true, paidEvent: true };
}

// Expose for integration
module.exports = { onCheckoutComplete, logConversion };
